constexpr float kKeypointVariance = 0.0100021362f;

// One axis of one warp: for output index i, the two source taps and their weights, with a
// weight of 0 where the tap falls outside [0, n-1] (grid_sample's zero padding). The
// arithmetic is the ONNX's, op for op, so the indices agree with it exactly.
struct Taps {
  int i0, i1;
  float w0, w1;
};

void axisTaps(const float* grid, int n, float shiftSource, float shiftTarget, bool identity,
              Taps* taps) {
  for (int i = 0; i < n; ++i) {
    const float c = identity ? grid[i] : (grid[i] - shiftSource) + shiftTarget;
    const float x = ((c + 1.0f) * (float)n) / 2.0f - 0.5f;
    const float f = std::floor(x);
    const float f1 = f + 1.0f;
    Taps& t = taps[i];
    t.w0 = f1 - x;
    t.w1 = x - f;
    const int a = (int)f, b = a + 1;
    if (a < 0 || a > n - 1) t.w0 = 0.0f;
    if (b < 0 || b > n - 1) t.w1 = 0.0f;
    t.i0 = a < 0 ? 0 : (a > n - 1 ? n - 1 : a);
    t.i1 = b < 0 ? 0 : (b > n - 1 ? n - 1 : b);
  }
}

// exp(-0.5 * (g - p)^2 / variance) along one axis; a voxel's Gaussian is the product of
// three of these (the ONNX takes exp of the sum -- the same value to float rounding).
void axisGauss(const float* grid, int n, float p, float* out) {
  for (int i = 0; i < n; ++i) {
    const float d = grid[i] - p;
    out[i] = std::exp((d * d * -0.5f) / kKeypointVariance);
  }
}

