void hourglassInput(const float* featureVolume, const float* source, const float* target,
                    float* out) {
  constexpr int kPlane = kH * kW;
  // compress: 1x1x1 conv 32 -> 4 (BatchNorm folded upstream), ReLU. Planar [4][voxels].
  std::vector<float> volume((size_t)kCompress * kVoxels);
  for (int c = 0; c < kCompress; ++c) {
    float* dst = volume.data() + (size_t)c * kVoxels;
    for (int v = 0; v < kVoxels; ++v) dst[v] = kCompressBias[c];
    for (int i = 0; i < kFeatureChannels; ++i) {
      const float w = kCompressWeight[c][i];
      const float* src = featureVolume + (size_t)i * kVoxels;
      for (int v = 0; v < kVoxels; ++v) dst[v] += w * src[v];
    }
    for (int v = 0; v < kVoxels; ++v) dst[v] = dst[v] > 0.0f ? dst[v] : 0.0f;
  }

  std::vector<float> alongW((size_t)kCompress * kVoxels), alongH((size_t)kCompress * kVoxels);
  std::vector<float> warped((size_t)kCompress * kVoxels);
  Taps tx[kW], ty[kH], tz[kD];
  float gx[kW], gy[kH], gz[kD], hx[kW], hy[kH], hz[kD];
  for (int k = 0; k < kMotions; ++k) {
    const bool identity = k == 0;
    const float* s = identity ? nullptr : source + 3 * (k - 1);
    const float* t = identity ? nullptr : target + 3 * (k - 1);
    axisTaps(kGridX, kW, identity ? 0.0f : s[0], identity ? 0.0f : t[0], identity, tx);
    axisTaps(kGridY, kH, identity ? 0.0f : s[1], identity ? 0.0f : t[1], identity, ty);
    axisTaps(kGridZ, kD, identity ? 0.0f : s[2], identity ? 0.0f : t[2], identity, tz);
    // W, then H, then D: each pass is a pair of taps per output index along one axis.
    for (int row = 0; row < kCompress * kD * kH; ++row) {
      const float* src = volume.data() + (size_t)row * kW;
      float* dst = alongW.data() + (size_t)row * kW;
      for (int x = 0; x < kW; ++x) dst[x] = tx[x].w0 * src[tx[x].i0] + tx[x].w1 * src[tx[x].i1];
    }
    for (int cd = 0; cd < kCompress * kD; ++cd) {
      const float* src = alongW.data() + (size_t)cd * kPlane;
      float* dst = alongH.data() + (size_t)cd * kPlane;
      for (int y = 0; y < kH; ++y) {
        const float* r0 = src + ty[y].i0 * kW;
        const float* r1 = src + ty[y].i1 * kW;
        const float w0 = ty[y].w0, w1 = ty[y].w1;
        float* o = dst + y * kW;
        for (int x = 0; x < kW; ++x) o[x] = w0 * r0[x] + w1 * r1[x];
      }
    }
    for (int c = 0; c < kCompress; ++c) {
      const float* src = alongH.data() + (size_t)c * kVoxels;
      float* dst = warped.data() + (size_t)c * kVoxels;
      for (int z = 0; z < kD; ++z) {
        const float* p0 = src + (size_t)tz[z].i0 * kPlane;
        const float* p1 = src + (size_t)tz[z].i1 * kPlane;
        const float w0 = tz[z].w0, w1 = tz[z].w1;
        float* o = dst + (size_t)z * kPlane;
        for (int i = 0; i < kPlane; ++i) o[i] = w0 * p0[i] + w1 * p1[i];
      }
    }
    // heatmap: Gaussian(source) - Gaussian(target), zero for the identity motion.
    if (!identity) {
      axisGauss(kGridX, kW, s[0], gx); axisGauss(kGridY, kH, s[1], gy); axisGauss(kGridZ, kD, s[2], gz);
      axisGauss(kGridX, kW, t[0], hx); axisGauss(kGridY, kH, t[1], hy); axisGauss(kGridZ, kD, t[2], hz);
    }
    // interleave into channels-last
    const int base = k * (1 + kCompress);
    for (int z = 0; z < kD; ++z) {
      for (int y = 0; y < kH; ++y) {
        const float gs = identity ? 0.0f : gz[z] * gy[y];
        const float gt = identity ? 0.0f : hz[z] * hy[y];
        const size_t row = ((size_t)z * kH + y) * kW;
        float* o = out + row * kHourglassChannels + base;
        for (int x = 0; x < kW; ++x, o += kHourglassChannels) {
          o[0] = identity ? 0.0f : gs * gx[x] - gt * hx[x];
          for (int c = 0; c < kCompress; ++c) o[1 + c] = warped[(size_t)c * kVoxels + row + x];
        }
      }
    }
  }
}

